// --- lib_rl.FDb.cand.AllocMem
// Allocate space for one element. If no memory available, return NULL.
void* lib_rl::cand_AllocMem() {
    u64 new_nelems     = _db.cand_n+1;
    // compute level and index on level
    u64 bsr   = algo::u64_BitScanReverse(new_nelems);
    u64 base  = u64(1)<<bsr;
    u64 index = new_nelems-base;
    void *ret = NULL;
    // if level doesn't exist yet, create it
    algo::cstring*  lev   = NULL;
    if (bsr < 36) {
        lev = _db.cand_lary[bsr];
        if (!lev) {
            lev=(algo::cstring*)algo_lib::malloc_AllocMem(sizeof(algo::cstring) * (u64(1)<<bsr));
            _db.cand_lary[bsr] = lev;
        }
    }
    // allocate element from this level
    if (lev) {
        _db.cand_n = i64(new_nelems);
        ret = lev + index;
    }
    return ret;
}

// --- lib_rl.FDb.cand.RemoveAll
// Remove all elements from Lary
void lib_rl::cand_RemoveAll() {
    for (u64 n = _db.cand_n; n>0; ) {
        n--;
        cand_qFind(u64(n)).~cstring(); // destroy last element
        _db.cand_n = i64(n);
    }
}

// --- lib_rl.FDb.cand.RemoveLast
// Delete last element of array. Do nothing if array is empty.
void lib_rl::cand_RemoveLast() {
    u64 n = _db.cand_n;
    if (n > 0) {
        n -= 1;
        cand_qFind(u64(n)).~cstring();
        _db.cand_n = i64(n);
    }
}

