// --- lib_rl.FDb..Init
// Set all fields to initial values.
void lib_rl::FDb_Init() {
    _db.line_valid = bool(false);
    _db.eof = bool(false);
    _db.err = i32(0);
    _db.isatty = bool(false);
    // initialize LAry cand (lib_rl.FDb.cand)
    _db.cand_n = 0;
    memset(_db.cand_lary, 0, sizeof(_db.cand_lary)); // zero out all level pointers
    algo::cstring* cand_first = (algo::cstring*)algo_lib::malloc_AllocMem(sizeof(algo::cstring) * (u64(1)<<4));
    if (!cand_first) {
        FatalErrorExit("out of memory");
    }
    for (int i = 0; i < 4; i++) {
        _db.cand_lary[i]  = cand_first;
        cand_first    += 1ULL<<i;
    }
    _db.point = i32(0);
    // initialize LAry hist (lib_rl.FDb.hist)
    _db.hist_n = 0;
    memset(_db.hist_lary, 0, sizeof(_db.hist_lary)); // zero out all level pointers
    algo::cstring* hist_first = (algo::cstring*)algo_lib::malloc_AllocMem(sizeof(algo::cstring) * (u64(1)<<4));
    if (!hist_first) {
        FatalErrorExit("out of memory");
    }
    for (int i = 0; i < 4; i++) {
        _db.hist_lary[i]  = hist_first;
        hist_first    += 1ULL<<i;
    }
    _db.hist_pos = i32(0);
    _db.search_pos = i32(0);
    _db.tab_last = bool(false);
    _db.cursor_row = i32(0);
    _db.tio_lflag = u64(0);
    _db.tio_vmin = u8(0);
    _db.tio_vtime = u8(0);

    lib_rl::InitReflection();
    _db.h_compl = NULL;
    _db.h_compl_ctx = 0;
}

